import math
from itertools import permutations

def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def sigma(m):
    s = 1
    temp = m
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            p = i
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p
            # Sum of divisors for p^count is (p^(count+1) - 1) / (p - 1)
            s *= (p**(count + 1) - 1) // (p - 1)
        i += 1
    if temp > 1:
        # Remaining prime factor
        s *= (temp**2 - 1) // (temp - 1) # temp + 1
    return s

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_m(m):
    divisors = get_divisors(m)
    n = len(divisors)

    # Optimization: Check if the total sum is a square. This is already guaranteed by the filtering step, 
    # but it's a good sanity check.
    total_sum = sigma(m)
    if not is_square(total_sum):
        return False # Should not happen based on outer loop logic, but safe.

    # Since n <= 12, we can iterate through permutations, but we must be careful about complexity.
    # Let's try the permutation approach for safety, but if performance is an issue, we'll use DFS.

    # Check all permutations (n! permutations)
    for p in permutations(divisors):
        current_sum = 0
        all_partial_sums_are_squares = True
        for i in range(n):
            current_sum += p[i]
            if not is_square(current_sum):
                all_partial_sums_are_squares = False
                break

        if all_partial_sums_are_squares:
            return True

    return False

# --- Main execution ---
solutions = []
for m in range(2, 101):
    s_m = sigma(m)
    if is_square(s_m):
        # print(f"Candidate m={m}, sigma(m)={s_m} (is square). Checking permutations...")
        if solve_m(m):
            solutions.append(m)

print("Found solutions m:", solutions)

